import { useEffect, useState, type FormEvent, type ReactNode } from 'react';
import { QueryClient, QueryClientProvider, useQueryClient } from '@tanstack/react-query';
import { Link, Route, Switch, useLocation, useParams, Router as WouterRouter } from 'wouter';
import {
  Activity, ArrowUpRight, BookOpen, BrainCircuit, CalendarDays, Check, ChevronRight, Circle, Clock3,
  FileText, Flame, FolderOpen, Gauge, Goal, LayoutDashboard, LogOut, Menu, MessageSquare, MoreHorizontal,
  Paperclip, Plus, Search, Send, Settings2, Sparkles, Target, Trash2, TrendingUp, Upload, X, Zap,
} from 'lucide-react';
import {
  createDocument, createGoal, createMeeting, createMemory, createMilestone, createReminder, deleteDocument,
  deleteGoal, deleteMeeting, deleteMemory, deleteReminder, getGetCurrentUserQueryKey, getGetDashboardQueryKey,
  getGetDocumentQueryKey, getGetGoalQueryKey,
  getListDocumentsQueryKey, getListGoalsQueryKey, getListMeetingsQueryKey, getListMemoriesQueryKey,
  getListRemindersQueryKey, getSearchKnowledgeQueryKey, login, logout, queryDocuments, register, sendChat,
  updateGoal, updateMemory, updateMilestone, updateReminder, deleteMilestone, uploadDocument, useGetCurrentUser, useGetDashboard, useGetDocument, useGetGoal,
  useGetGrowth, useGetTimeline, useListDocuments, useListGoals, useListMeetings, useListMemories,
  useListReminders, useSearchKnowledge,
} from '@workspace/api-client-react';
import type { Goal as GoalType, Memory, User } from '@workspace/api-client-react';
import NotFound from '@/pages/not-found';

const queryClient = new QueryClient();
const nav = [
  { href: '/', label: 'Command center', icon: LayoutDashboard },
  { href: '/chat', label: 'Companion', icon: MessageSquare },
  { href: '/memory', label: 'Memory', icon: BrainCircuit },
  { href: '/knowledge', label: 'Knowledge', icon: Search },
  { href: '/goals', label: 'Goals', icon: Target },
  { href: '/growth', label: 'Growth', icon: TrendingUp },
  { href: '/meetings', label: 'Meetings', icon: CalendarDays },
  { href: '/documents', label: 'Documents', icon: FolderOpen },
  { href: '/analytics', label: 'Activity', icon: Activity },
];
const dateLabel = (value?: string | null) => value ? new Intl.DateTimeFormat('en', { month: 'short', day: 'numeric', year: 'numeric' }).format(new Date(value)) : 'No date';
const timeLabel = (value?: string | null) => value ? new Intl.DateTimeFormat('en', { hour: 'numeric', minute: '2-digit' }).format(new Date(value)) : '';
const initials = (name?: string) => (name || 'J').split(' ').map((part) => part[0]).slice(0, 2).join('').toUpperCase();
const cx = (...classes: Array<string | false | undefined>) => classes.filter(Boolean).join(' ');

function Button({ children, variant = 'primary', className, ...props }: { children: ReactNode; variant?: 'primary' | 'quiet' | 'outline' | 'danger'; className?: string; [key: string]: unknown }) {
  const styles = { primary: 'bg-primary text-primary-foreground hover:opacity-90', quiet: 'bg-secondary text-secondary-foreground hover:bg-muted', outline: 'border border-border bg-card hover:bg-muted', danger: 'border border-destructive/30 text-destructive hover:bg-destructive/10' };
  return <button className={cx('inline-flex items-center justify-center gap-2 rounded-lg px-3.5 py-2 text-sm font-semibold transition-all duration-200 disabled:cursor-not-allowed disabled:opacity-45', styles[variant], className)} {...props}>{children}</button>;
}
function Field({ label, children, hint }: { label: string; children: ReactNode; hint?: string }) {
  return <label className="grid gap-1.5 text-sm font-semibold text-foreground"><span>{label}</span>{children}{hint && <span className="text-xs font-normal text-muted-foreground">{hint}</span>}</label>;
}
function Input(props: React.InputHTMLAttributes<HTMLInputElement>) {
  return <input {...props} className={cx('h-10 w-full rounded-lg border border-input bg-background/75 px-3 text-sm outline-none transition focus:border-primary focus:ring-2 focus:ring-primary/15', props.className)} />;
}
function Textarea(props: React.TextareaHTMLAttributes<HTMLTextAreaElement>) {
  return <textarea {...props} className={cx('min-h-28 w-full resize-y rounded-lg border border-input bg-background/75 px-3 py-2.5 text-sm leading-6 outline-none transition focus:border-primary focus:ring-2 focus:ring-primary/15', props.className)} />;
}
function Empty({ icon: Icon, title, body, action }: { icon: typeof Search; title: string; body: string; action?: ReactNode }) {
  return <div className="panel flex min-h-64 flex-col items-center justify-center px-6 text-center"><div className="mb-4 rounded-full bg-secondary p-3 text-primary"><Icon size={21} /></div><h3 className="font-serif text-2xl">{title}</h3><p className="mt-2 max-w-sm text-sm leading-6 text-muted-foreground">{body}</p>{action && <div className="mt-5">{action}</div>}</div>;
}
function Skeleton({ className = '' }: { className?: string }) { return <div className={cx('animate-pulse rounded-lg bg-muted', className)} />; }
function Toast({ message, onClose }: { message: string; onClose: () => void }) { return <div className="fixed bottom-5 right-5 z-50 flex max-w-sm items-center gap-3 rounded-lg bg-sidebar px-4 py-3 text-sm text-sidebar-foreground shadow-xl"><Check size={16} className="text-accent" />{message}<button data-testid="button-close-toast" onClick={onClose} className="ml-2 opacity-60 hover:opacity-100"><X size={15} /></button></div>; }

function AuthPage({ mode }: { mode: 'login' | 'register' }) {
  const [, setLocation] = useLocation();
  const [form, setForm] = useState({ name: '', email: '', password: '' });
  const [error, setError] = useState('');
  const [pending, setPending] = useState(false);
  const submit = async (event: FormEvent) => {
    event.preventDefault(); setPending(true); setError('');
    try {
      const user = mode === 'login' ? await login({ email: form.email, password: form.password }) : await register(form);
      queryClient.setQueryData(getGetCurrentUserQueryKey(), user); setLocation('/');
    } catch (err) { setError(err instanceof Error ? err.message : 'Unable to continue. Check your details and try again.'); }
    finally { setPending(false); }
  };
  return <main className="jarvis-noise flex min-h-[100dvh] bg-background">
    <section className="hidden w-[47%] flex-col justify-between overflow-hidden bg-sidebar p-12 text-sidebar-foreground lg:flex">
      <div><div className="flex items-center gap-3"><span className="grid size-9 place-items-center rounded-lg bg-accent text-sidebar"><Sparkles size={18} /></span><span className="font-mono text-sm tracking-[.22em]">JARVIS</span></div><div className="mt-28 max-w-md"><div className="eyebrow text-accent">Personal operating system</div><h1 className="mt-5 font-serif text-6xl leading-[.98]">A quieter way<br />to move forward.</h1><p className="mt-7 max-w-sm text-sm leading-7 text-sidebar-foreground/65">Your context, held carefully. Your next step, made visible.</p></div></div>
      <div className="flex items-center gap-3 text-xs text-sidebar-foreground/50"><span className="size-2 rounded-full bg-accent animate-pulse-soft" />Your private command center</div>
    </section>
    <section className="flex w-full items-center justify-center px-6 py-12 lg:w-[53%]"><div className="w-full max-w-[420px] animate-rise">
      <div className="mb-12 lg:hidden"><div className="flex items-center gap-3"><span className="grid size-9 place-items-center rounded-lg bg-primary text-primary-foreground"><Sparkles size={18} /></span><span className="font-mono text-sm tracking-[.22em]">JARVIS</span></div></div>
      <div className="eyebrow">Welcome back to your context</div><h2 className="mt-3 font-serif text-4xl">{mode === 'login' ? 'Sign in to JARVIS' : 'Create your workspace'}</h2><p className="mt-3 text-sm leading-6 text-muted-foreground">{mode === 'login' ? 'Pick up exactly where your thinking left off.' : 'A thoughtful place for the things that make you, you.'}</p>
      <form onSubmit={submit} className="mt-9 grid gap-5">
        {mode === 'register' && <Field label="Your name"><Input data-testid="input-name" required value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} placeholder="What should JARVIS call you?" /></Field>}
         <Field label="Email"><Input data-testid="input-email" type="email" autoComplete="email" required value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} placeholder="you@example.com" /></Field>
         <Field label="Password"><Input data-testid="input-password" type="password" autoComplete={mode === 'login' ? 'current-password' : 'new-password'} required minLength={mode === 'register' ? 8 : 1} value={form.password} onChange={(e) => setForm({ ...form, password: e.target.value })} placeholder="Your private key" /></Field>
        {error && <div data-testid="status-auth-error" className="rounded-lg border border-destructive/30 bg-destructive/10 px-3 py-2 text-sm text-destructive">{error}</div>}
        <Button data-testid="button-auth-submit" disabled={pending} className="mt-1 h-11">{pending ? 'Connecting…' : mode === 'login' ? 'Enter JARVIS' : 'Open my workspace'}<ArrowUpRight size={16} /></Button>
      </form>
      <p className="mt-7 text-center text-sm text-muted-foreground">{mode === 'login' ? 'New here? ' : 'Already have an account? '}<Link data-testid="link-auth-switch" href={mode === 'login' ? '/register' : '/login'} className="font-semibold text-primary hover:underline">{mode === 'login' ? 'Create an account' : 'Sign in'}</Link></p>
    </div></section>
  </main>;
}

function Shell({ children, user }: { children: ReactNode; user: User }) {
  const [location, setLocation] = useLocation(); const [open, setOpen] = useState(false); const [loggingOut, setLoggingOut] = useState(false);
  const signOut = async () => { setLoggingOut(true); await logout(); queryClient.clear(); setLocation('/login'); };
  return <div className="jarvis-noise min-h-[100dvh] bg-background">
    <aside className={cx('fixed inset-y-0 left-0 z-40 w-[244px] -translate-x-full border-r border-sidebar-border bg-sidebar text-sidebar-foreground transition-transform md:translate-x-0', open && 'translate-x-0')}><div className="flex h-full flex-col p-4">
      <div className="flex items-center justify-between px-2 py-3"><Link href="/" data-testid="link-logo" className="flex items-center gap-3"><span className="grid size-8 place-items-center rounded-lg bg-accent text-sidebar"><Sparkles size={16} /></span><span className="font-mono text-xs tracking-[.2em]">JARVIS</span></Link><button data-testid="button-close-menu" onClick={() => setOpen(false)} className="md:hidden"><X size={18} /></button></div>
      <div className="mb-4 mt-7 px-2 text-[10px] uppercase tracking-[.18em] text-sidebar-foreground/40">Your operating system</div>
      <nav className="grid gap-1">{nav.map((item) => { const Icon = item.icon; const active = location === item.href; return <Link key={item.href} data-testid={`link-nav-${item.label.toLowerCase().replaceAll(' ', '-')}`} href={item.href} onClick={() => setOpen(false)} className={cx('group flex items-center gap-3 rounded-lg px-3 py-2.5 text-sm text-sidebar-foreground/65 transition hover:bg-sidebar-accent hover:text-sidebar-foreground', active && 'bg-sidebar-accent text-sidebar-foreground')}><Icon size={16} className={cx(active ? 'text-accent' : 'text-sidebar-foreground/45', 'transition')} /><span>{item.label}</span>{active && <span className="ml-auto size-1.5 rounded-full bg-accent" />}</Link>; })}</nav>
      <div className="mt-auto grid gap-1 border-t border-sidebar-border pt-4"><Link href="/settings" data-testid="link-nav-settings" className="flex items-center gap-3 rounded-lg px-3 py-2.5 text-sm text-sidebar-foreground/65 hover:bg-sidebar-accent hover:text-sidebar-foreground"><Settings2 size={16} />Settings</Link><button data-testid="button-logout" onClick={signOut} disabled={loggingOut} className="flex items-center gap-3 rounded-lg px-3 py-2.5 text-left text-sm text-sidebar-foreground/65 hover:bg-sidebar-accent hover:text-sidebar-foreground"><LogOut size={16} />{loggingOut ? 'Leaving…' : 'Sign out'}</button><div className="mt-3 flex items-center gap-3 rounded-lg bg-sidebar-accent/55 p-3"><div className="grid size-8 place-items-center rounded-full bg-accent text-xs font-bold text-sidebar">{initials(user.name)}</div><div className="min-w-0"><div data-testid="text-user-name" className="truncate text-xs font-semibold">{user.name}</div><div className="truncate text-[10px] text-sidebar-foreground/45">{user.email}</div></div></div></div>
    </div></aside>
    {open && <button data-testid="button-menu-backdrop" onClick={() => setOpen(false)} className="fixed inset-0 z-30 bg-sidebar/30 md:hidden" />}
    <div className="md:pl-[244px]"><header className="sticky top-0 z-20 flex h-[68px] items-center justify-between border-b border-border/70 bg-background/85 px-5 backdrop-blur-md md:px-10"><button data-testid="button-open-menu" onClick={() => setOpen(true)} className="rounded-lg p-2 hover:bg-muted md:hidden"><Menu size={20} /></button><div className="hidden md:block"><span className="eyebrow">{new Intl.DateTimeFormat('en', { weekday: 'long', month: 'long', day: 'numeric' }).format(new Date())}</span></div><div className="ml-auto flex items-center gap-3"><Link href="/chat" data-testid="link-header-chat" className="flex items-center gap-2 rounded-lg border border-border bg-card px-3 py-2 text-xs font-semibold hover:bg-muted"><Sparkles size={14} className="text-accent" />Ask JARVIS</Link><div className="grid size-8 place-items-center rounded-full bg-primary text-xs font-bold text-primary-foreground">{initials(user.name)}</div></div></header><main className="mx-auto max-w-[1440px] px-5 py-8 md:px-10 md:py-10">{children}</main></div>
  </div>;
}
function PageHeading({ eyebrow, title, body, action }: { eyebrow: string; title: string; body?: string; action?: ReactNode }) { return <div className="mb-8 flex flex-col justify-between gap-5 md:flex-row md:items-end"><div><div className="eyebrow">{eyebrow}</div><h1 className="mt-2 font-serif text-4xl leading-tight md:text-5xl">{title}</h1>{body && <p className="mt-3 max-w-2xl text-sm leading-6 text-muted-foreground">{body}</p>}</div>{action}</div>; }
function Stat({ label, value, detail, icon: Icon }: { label: string; value: string | number; detail?: string; icon: typeof Zap }) { return <div className="panel p-5"><div className="flex items-center justify-between"><span className="eyebrow">{label}</span><Icon size={16} className="text-primary" /></div><div data-testid={`stat-${label.toLowerCase().replaceAll(' ', '-')}`} className="mt-4 font-serif text-3xl">{value}</div>{detail && <div className="mt-1 text-xs text-muted-foreground">{detail}</div>}</div>; }

function DashboardPage() {
  const { data, isLoading, isError, refetch } = useGetDashboard(); const [, setLocation] = useLocation(); const [chat, setChat] = useState(''); const [answer, setAnswer] = useState(''); const [pending, setPending] = useState(false);
  if (isLoading) return <div className="grid gap-5"><Skeleton className="h-48" /><div className="grid gap-5 md:grid-cols-4">{[1, 2, 3, 4].map((i) => <Skeleton key={i} className="h-32" />)}</div></div>;
  if (isError || !data) return <Empty icon={Activity} title="The command center is quiet" body="JARVIS could not reach your workspace. Try again when you are ready." action={<Button data-testid="button-retry-dashboard" onClick={() => refetch()}>Try again</Button>} />;
  const ask = async (e: FormEvent) => { e.preventDefault(); if (!chat.trim()) return; setPending(true); setAnswer(''); try { const res = await sendChat({ message: chat }); setAnswer(res.reply); } catch { setAnswer('I could not connect just now. Your question is still here when you return.'); } finally { setPending(false); } };
  return <div className="animate-rise"><div className="mb-8 flex flex-col justify-between gap-5 md:flex-row md:items-end"><div><div className="eyebrow">Command center / {timeLabel(new Date().toISOString())}</div><h1 data-testid="text-dashboard-greeting" className="mt-2 font-serif text-4xl leading-tight md:text-5xl">{data.greeting || 'Good to see you.'}</h1><p className="mt-3 text-sm text-muted-foreground">Here is the shape of your attention today.</p></div><Button data-testid="button-open-chat" onClick={() => setLocation('/chat')}><Sparkles size={15} />Open companion</Button></div>
    <section className="relative overflow-hidden rounded-2xl bg-sidebar p-6 text-sidebar-foreground md:p-8"><div className="absolute -right-16 -top-20 size-64 rounded-full border border-accent/20" /><div className="absolute -right-4 -top-8 size-40 rounded-full border border-accent/15" /><div className="relative max-w-2xl"><div className="eyebrow text-accent">Current focus</div><h2 data-testid="text-current-focus" className="mt-4 font-serif text-3xl leading-tight md:text-4xl">{data.focus || 'Choose one meaningful thing to carry forward.'}</h2><div className="mt-7 flex flex-wrap gap-3"><span className="rounded-full border border-sidebar-border px-3 py-1.5 font-mono text-[10px] text-sidebar-foreground/60">{data.activeGoals} active goals</span><span className="rounded-full border border-sidebar-border px-3 py-1.5 font-mono text-[10px] text-sidebar-foreground/60">{data.streak} day streak</span></div></div></section>
    <div className="mt-5 grid gap-4 sm:grid-cols-3"><Stat label="Momentum" value={`${data.xp} XP`} detail={`Level ${data.level}`} icon={Zap} /><Stat label="Active goals" value={data.activeGoals} detail={`${data.completedGoals} completed`} icon={Target} /><Stat label="Streak" value={`${data.streak} days`} detail="Keep the thread alive" icon={Flame} /></div>
    <div className="mt-5 grid gap-5 lg:grid-cols-[1.15fr_.85fr]"><section className="panel p-5 md:p-6"><div className="mb-5 flex items-center justify-between"><div><div className="eyebrow">Next up</div><h2 className="mt-1 font-serif text-2xl">Reminders</h2></div><Link data-testid="link-dashboard-goals" href="/goals" className="text-xs font-semibold text-primary hover:underline">View goals</Link></div>{data.upcomingReminders?.length ? <div className="grid gap-3">{data.upcomingReminders.slice(0, 4).map((item) => <div key={item.id} data-testid={`row-reminder-${item.id}`} className="flex items-start gap-3 rounded-lg border border-border/70 p-3"><span className="mt-1 size-2 rounded-full bg-accent" /><div className="min-w-0 flex-1"><div className="text-sm font-semibold">{item.title}</div><div className="mt-1 text-xs text-muted-foreground">{item.description || 'No description'}</div></div><time className="font-mono text-[10px] text-muted-foreground">{timeLabel(item.dueAt)}</time></div>)}</div> : <Empty icon={Clock3} title="Clear runway" body="No reminders are waiting for you." action={<Link href="/goals" data-testid="link-add-reminder" className="text-sm font-semibold text-primary">Set a goal <ChevronRight size={14} className="inline" /></Link>} />}</section>
      <section className="panel p-5 md:p-6"><div className="mb-5 flex items-center justify-between"><div><div className="eyebrow">Ask anything</div><h2 className="mt-1 font-serif text-2xl">Quick chat</h2></div><MessageSquare size={18} className="text-primary" /></div><form onSubmit={ask} className="relative"><Input data-testid="input-quick-chat" value={chat} onChange={(e) => setChat(e.target.value)} placeholder="What should I focus on?" className="h-12 pr-12" /><button data-testid="button-send-quick-chat" disabled={pending} className="absolute right-2 top-2 grid size-8 place-items-center rounded-md bg-primary text-primary-foreground"><Send size={14} /></button></form>{answer && <div data-testid="text-quick-chat-answer" className="mt-4 rounded-lg bg-secondary p-4 text-sm leading-6 text-secondary-foreground">{answer}</div>}<div className="mt-5 grid gap-2">{['What is falling through the cracks?', 'Help me make a plan for today'].map((prompt) => <button key={prompt} data-testid={`button-suggestion-${prompt.slice(0, 8)}`} onClick={() => setChat(prompt)} className="flex items-center justify-between rounded-lg border border-border/70 px-3 py-2.5 text-left text-xs text-muted-foreground hover:bg-muted"><span>{prompt}</span><ArrowUpRight size={13} /></button>)}</div></section></div>
    <section className="mt-5 grid gap-5 md:grid-cols-3"><ActivityList title="Recent memories" icon={BrainCircuit} items={(data.recentMemories || []).map((x) => ({ id: x.id, title: x.content, meta: x.category }))} href="/memory" /><ActivityList title="Documents" icon={FileText} items={(data.recentDocuments || []).map((x) => ({ id: x.id, title: x.title || x.filename, meta: x.processingStatus }))} href="/documents" /><ActivityList title="Meetings" icon={CalendarDays} items={(data.recentMeetings || []).map((x) => ({ id: x.id, title: x.title, meta: dateLabel(x.meetingDate) }))} href="/meetings" /></section><div className="mt-5"><RemindersPanel /></div>
  </div>;
}
function ActivityList({ title, icon: Icon, items, href }: { title: string; icon: typeof BrainCircuit; items: Array<{ id: number; title: string; meta: string }>; href: string }) { return <section className="panel p-5"><div className="mb-4 flex items-center justify-between"><div className="flex items-center gap-2"><Icon size={16} className="text-primary" /><h3 className="text-sm font-bold">{title}</h3></div><Link href={href} data-testid={`link-view-${title.toLowerCase()}`}><ChevronRight size={16} className="text-muted-foreground" /></Link></div>{items.length ? <div className="grid gap-3">{items.slice(0, 3).map((item) => <div key={item.id} data-testid={`item-${title.toLowerCase()}-${item.id}`} className="border-b border-border/60 pb-3 last:border-0 last:pb-0"><div className="line-clamp-2 text-sm leading-5">{item.title}</div><div className="mt-1 font-mono text-[10px] uppercase tracking-wider text-muted-foreground">{item.meta}</div></div>)}</div> : <p className="py-5 text-sm text-muted-foreground">Nothing here yet.</p>}</section>; }

function MemoryPage() {
  const { data, isLoading, refetch } = useListMemories(); const qc = useQueryClient(); const [editing, setEditing] = useState<Memory | null>(null); const [composer, setComposer] = useState(false); const [toast, setToast] = useState(''); const [form, setForm] = useState({ content: '', category: 'personal', importance: '3' });
  const reset = () => { setForm({ content: '', category: 'personal', importance: '3' }); setEditing(null); setComposer(false); };
  const save = async (e: FormEvent) => { e.preventDefault(); try { if (editing) await updateMemory(editing.id, { content: form.content, category: form.category, importance: Number(form.importance) }); else await createMemory({ content: form.content, category: form.category, importance: Number(form.importance) }); await qc.invalidateQueries({ queryKey: getListMemoriesQueryKey() }); reset(); setToast('Memory saved to your context.'); } catch { setToast('Could not save that memory.'); } };
  const remove = async (id: number) => { if (!window.confirm('Delete this memory?')) return; await deleteMemory(id); await qc.invalidateQueries({ queryKey: getListMemoriesQueryKey() }); setToast('Memory removed.'); };
  return <div className="animate-rise"><PageHeading eyebrow="Persistent context" title="Memory" body="The small truths, preferences, and patterns that help JARVIS know you over time." action={<Button data-testid="button-new-memory" onClick={() => setComposer(true)}><Plus size={16} />Add memory</Button>} />{(composer || editing) && <form onSubmit={save} className="panel mb-6 grid gap-4 p-5 md:p-6"><div className="flex items-center justify-between"><h2 className="font-serif text-2xl">{editing ? 'Edit memory' : 'Capture a thought'}</h2><button type="button" data-testid="button-close-memory-form" onClick={reset}><X size={18} /></button></div><Field label="What should JARVIS remember?"><Textarea data-testid="input-memory-content" required value={form.content} onChange={(e) => setForm({ ...form, content: e.target.value })} placeholder="I do my best thinking before noon…" /></Field><div className="grid gap-4 md:grid-cols-2"><Field label="Category"><Input data-testid="input-memory-category" value={form.category} onChange={(e) => setForm({ ...form, category: e.target.value })} /></Field><Field label="Importance"><select data-testid="select-memory-importance" value={form.importance} onChange={(e) => setForm({ ...form, importance: e.target.value })} className="h-10 rounded-lg border border-input bg-background px-3 text-sm"><option value="1">1 · Useful</option><option value="3">3 · Important</option><option value="5">5 · Essential</option></select></Field></div><div className="flex justify-end gap-2"><Button type="button" variant="quiet" data-testid="button-cancel-memory" onClick={reset}>Cancel</Button><Button data-testid="button-save-memory"><Check size={15} />Save memory</Button></div></form>}{isLoading ? <div className="grid gap-3">{[1, 2, 3].map((i) => <Skeleton key={i} className="h-28" />)}</div> : data?.length ? <div className="grid gap-3">{data.map((item) => <article key={item.id} data-testid={`card-memory-${item.id}`} className="panel group p-5 transition hover:-translate-y-0.5 hover:shadow-md"><div className="flex items-start gap-4"><div className="mt-1 grid size-9 shrink-0 place-items-center rounded-lg bg-secondary text-primary"><BrainCircuit size={17} /></div><div className="min-w-0 flex-1"><p className="leading-7">{item.content}</p><div className="mt-4 flex flex-wrap items-center gap-2"><span className="rounded-full bg-secondary px-2.5 py-1 font-mono text-[10px] uppercase tracking-wider text-secondary-foreground">{item.category || 'uncategorized'}</span><span className="text-xs text-muted-foreground">Importance {item.importance}/5 · {dateLabel(item.updatedAt)}</span></div></div><div className="flex gap-1 opacity-0 transition group-hover:opacity-100"><button data-testid={`button-edit-memory-${item.id}`} onClick={() => { setEditing(item); setForm({ content: item.content, category: item.category, importance: String(item.importance) }); }} className="rounded-md p-2 text-muted-foreground hover:bg-muted hover:text-foreground"><MoreHorizontal size={17} /></button><button data-testid={`button-delete-memory-${item.id}`} onClick={() => remove(item.id)} className="rounded-md p-2 text-muted-foreground hover:bg-destructive/10 hover:text-destructive"><Trash2 size={16} /></button></div></div></article>)}</div> : <Empty icon={BrainCircuit} title="A clean slate" body="Store a preference, a pattern, or a detail you want JARVIS to carry into the future." action={<Button data-testid="button-empty-add-memory" onClick={() => setComposer(true)}><Plus size={15} />Add your first memory</Button>} />}{toast && <Toast message={toast} onClose={() => setToast('')} />}</div>;
}

function GoalMilestones({ goalId }: { goalId: number }) {
  const detail = useGetGoal(goalId, { query: { queryKey: getGetGoalQueryKey(goalId) } }); const qc = useQueryClient(); const [title, setTitle] = useState(''); const [adding, setAdding] = useState(false);
  const add = async (e: FormEvent) => { e.preventDefault(); if (!title.trim()) return; await createMilestone(goalId, { title }); await qc.invalidateQueries({ queryKey: getGetGoalQueryKey(goalId) }); setTitle(''); setAdding(false); };
  const toggle = async (id: number, status: string) => { await updateMilestone(id, { status: status === 'completed' ? 'pending' : 'completed', progress: status === 'completed' ? 0 : 100 }); await qc.invalidateQueries({ queryKey: getGetGoalQueryKey(goalId) }); };
  const remove = async (id: number) => { if (!window.confirm('Delete this milestone?')) return; await deleteMilestone(id); await qc.invalidateQueries({ queryKey: getGetGoalQueryKey(goalId) }); };
  return <div className="mt-5 border-t border-border/70 pt-4"><div className="flex items-center justify-between"><span className="eyebrow">Milestones</span><button data-testid={`button-add-milestone-${goalId}`} onClick={() => setAdding(!adding)} className="flex items-center gap-1 text-xs font-semibold text-primary"><Plus size={13} />Add</button></div>{adding && <form onSubmit={add} className="mt-3 flex gap-2"><Input data-testid={`input-milestone-${goalId}`} required value={title} onChange={(e) => setTitle(e.target.value)} placeholder="A small, finishable step" /><Button data-testid={`button-save-milestone-${goalId}`}>Add step</Button></form>}{detail.isLoading ? <Skeleton className="mt-3 h-8" /> : detail.data?.milestones?.length ? <div className="mt-3 grid gap-2">{detail.data.milestones.map((milestone) => <div key={milestone.id} data-testid={`row-milestone-${milestone.id}`} className="flex items-center gap-2 text-sm"><button data-testid={`button-complete-milestone-${milestone.id}`} onClick={() => toggle(milestone.id, milestone.status)} className={cx('grid size-4 place-items-center rounded-full border', milestone.status === 'completed' ? 'border-primary bg-primary text-primary-foreground' : 'border-border')}>{milestone.status === 'completed' && <Check size={10} />}</button><span className={cx('flex-1', milestone.status === 'completed' && 'text-muted-foreground line-through')}>{milestone.title}</span><button data-testid={`button-delete-milestone-${milestone.id}`} onClick={() => remove(milestone.id)} className="p-1 text-muted-foreground hover:text-destructive"><Trash2 size={13} /></button></div>)}</div> : <p className="mt-3 text-xs text-muted-foreground">Break this goal into a first small step.</p>}</div>;
}

function GoalsPage() {
  const { data, isLoading } = useListGoals(); const qc = useQueryClient(); const [composer, setComposer] = useState(false); const [editing, setEditing] = useState<GoalType | null>(null); const [toast, setToast] = useState(''); const [form, setForm] = useState({ title: '', description: '', category: 'personal', priority: 'medium', deadline: '' });
  const reset = () => { setComposer(false); setEditing(null); setForm({ title: '', description: '', category: 'personal', priority: 'medium', deadline: '' }); };
  const save = async (e: FormEvent) => { e.preventDefault(); try { if (editing) await updateGoal(editing.id, { ...form, deadline: form.deadline || null }); else await createGoal({ ...form, deadline: form.deadline || null }); await qc.invalidateQueries({ queryKey: getListGoalsQueryKey() }); await qc.invalidateQueries({ queryKey: getGetDashboardQueryKey() }); reset(); setToast('Goal updated.'); } catch { setToast('Could not save that goal.'); } };
  const complete = async (goal: GoalType) => { await updateGoal(goal.id, { status: goal.status === 'completed' ? 'active' : 'completed', progress: goal.status === 'completed' ? goal.progress : 100 }); await qc.invalidateQueries({ queryKey: getListGoalsQueryKey() }); setToast(goal.status === 'completed' ? 'Goal reopened.' : 'Goal completed.'); };
  const remove = async (id: number) => { if (!window.confirm('Delete this goal and its milestones?')) return; await deleteGoal(id); await qc.invalidateQueries({ queryKey: getListGoalsQueryKey() }); setToast('Goal deleted.'); };
  return <div className="animate-rise"><PageHeading eyebrow="Forward motion" title="Goals" body="Make progress visible. Keep the important work close enough to touch." action={<Button data-testid="button-new-goal" onClick={() => setComposer(true)}><Plus size={16} />New goal</Button>} />{(composer || editing) && <form onSubmit={save} className="panel mb-6 grid gap-4 p-5 md:p-6"><div className="flex items-center justify-between"><h2 className="font-serif text-2xl">{editing ? 'Edit goal' : 'Name a direction'}</h2><button type="button" data-testid="button-close-goal-form" onClick={reset}><X size={18} /></button></div><Field label="Title"><Input data-testid="input-goal-title" required value={form.title} onChange={(e) => setForm({ ...form, title: e.target.value })} placeholder="The thing worth moving toward" /></Field><Field label="Description"><Textarea data-testid="input-goal-description" value={form.description} onChange={(e) => setForm({ ...form, description: e.target.value })} placeholder="Why does this matter?" /></Field><div className="grid gap-4 sm:grid-cols-3"><Field label="Category"><Input data-testid="input-goal-category" value={form.category} onChange={(e) => setForm({ ...form, category: e.target.value })} /></Field><Field label="Priority"><select data-testid="select-goal-priority" value={form.priority} onChange={(e) => setForm({ ...form, priority: e.target.value })} className="h-10 rounded-lg border border-input bg-background px-3 text-sm"><option>low</option><option>medium</option><option>high</option></select></Field><Field label="Deadline"><Input data-testid="input-goal-deadline" type="date" value={form.deadline} onChange={(e) => setForm({ ...form, deadline: e.target.value })} /></Field></div><div className="flex justify-end gap-2"><Button type="button" variant="quiet" data-testid="button-cancel-goal" onClick={reset}>Cancel</Button><Button data-testid="button-save-goal">Save goal</Button></div></form>}{isLoading ? <div className="grid gap-4">{[1, 2].map((i) => <Skeleton key={i} className="h-40" />)}</div> : data?.length ? <div className="grid gap-4">{data.map((goal) => <article key={goal.id} data-testid={`card-goal-${goal.id}`} className="panel p-5 md:p-6"><div className="flex flex-col gap-4 md:flex-row md:items-start"><button data-testid={`button-complete-goal-${goal.id}`} onClick={() => complete(goal)} className={cx('mt-1 grid size-6 shrink-0 place-items-center rounded-full border-2 transition', goal.status === 'completed' ? 'border-primary bg-primary text-primary-foreground' : 'border-border hover:border-primary')}>{goal.status === 'completed' && <Check size={14} />}</button><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><h2 className="font-serif text-2xl">{goal.title}</h2><span className="rounded-full bg-secondary px-2 py-1 font-mono text-[9px] uppercase tracking-wider">{goal.category}</span></div><p className="mt-2 max-w-2xl text-sm leading-6 text-muted-foreground">{goal.description || 'No description yet.'}</p><div className="mt-5 flex items-center gap-3"><div className="h-2 flex-1 overflow-hidden rounded-full bg-muted"><div className="h-full rounded-full bg-primary transition-all" style={{ width: `${goal.progress}%` }} /></div><span className="font-mono text-xs">{goal.progress}%</span></div><div className="mt-3 flex flex-wrap gap-4 text-[11px] text-muted-foreground"><span className="uppercase tracking-wider text-accent">{goal.priority} priority</span><span>{goal.deadline ? `Due ${dateLabel(goal.deadline)}` : 'No deadline'}</span></div></div><div className="flex gap-1"><button data-testid={`button-edit-goal-${goal.id}`} onClick={() => { setEditing(goal); setForm({ title: goal.title, description: goal.description, category: goal.category, priority: goal.priority, deadline: goal.deadline?.slice(0, 10) || '' }); }} className="rounded-md p-2 text-muted-foreground hover:bg-muted"><Settings2 size={16} /></button><button data-testid={`button-delete-goal-${goal.id}`} onClick={() => remove(goal.id)} className="rounded-md p-2 text-muted-foreground hover:bg-destructive/10 hover:text-destructive"><Trash2 size={16} /></button></div></div><GoalMilestones goalId={goal.id} /></article>)}</div> : <Empty icon={Target} title="Give your attention a direction" body="A good goal is a promise to your future self. Start with one that matters." action={<Button data-testid="button-empty-add-goal" onClick={() => setComposer(true)}><Plus size={15} />Create a goal</Button>} />}{toast && <Toast message={toast} onClose={() => setToast('')} />}</div>;
}

function ChatPage() {
  const [messages, setMessages] = useState<Array<{ role: 'user' | 'assistant'; text: string; sources?: Array<{ title: string; excerpt: string }> }>>([]); const [value, setValue] = useState(''); const [pending, setPending] = useState(false);
  const submit = async (e: FormEvent) => { e.preventDefault(); if (!value.trim() || pending) return; const current = value; setValue(''); setMessages((old) => [...old, { role: 'user', text: current }]); setPending(true); try { const res = await sendChat({ message: current }); setMessages((old) => [...old, { role: 'assistant', text: res.reply, sources: res.sources }]); } catch { setMessages((old) => [...old, { role: 'assistant', text: 'I could not reach your context right now. Try again in a moment.' }]); } finally { setPending(false); } };
  return <div className="mx-auto flex min-h-[calc(100dvh-148px)] max-w-4xl flex-col animate-rise"><PageHeading eyebrow="Context-aware companion" title="Talk it through." body="JARVIS can connect the dots across what you remember, what you are working toward, and what is next." /><div className="panel flex flex-1 flex-col overflow-hidden"><div className="flex-1 space-y-5 overflow-y-auto p-5 md:p-8">{messages.length === 0 && <div className="flex min-h-[300px] flex-col items-center justify-center text-center"><div className="grid size-14 place-items-center rounded-2xl bg-secondary text-primary"><Sparkles size={24} /></div><h2 className="mt-5 font-serif text-3xl">What is on your mind?</h2><p className="mt-2 max-w-sm text-sm leading-6 text-muted-foreground">Ask for a plan, a pattern, a reminder of what you already know, or a more honest next step.</p><div className="mt-7 flex flex-wrap justify-center gap-2">{['Help me find the thread', 'What should I prioritize?', 'Summarize my recent context'].map((x) => <button key={x} data-testid={`button-chat-prompt-${x.slice(0, 5)}`} onClick={() => setValue(x)} className="rounded-full border border-border px-3 py-2 text-xs text-muted-foreground hover:bg-muted">{x}</button>)}</div></div>}{messages.map((message, index) => <div key={index} data-testid={`chat-message-${index}`} className={cx('flex', message.role === 'user' ? 'justify-end' : 'justify-start')}><div className={cx('max-w-[85%] rounded-2xl px-4 py-3 text-sm leading-7', message.role === 'user' ? 'rounded-br-sm bg-primary text-primary-foreground' : 'rounded-bl-sm bg-secondary text-secondary-foreground')}><div>{message.text}</div>{message.sources?.length ? <div className="mt-4 border-t border-secondary-foreground/15 pt-3"><div className="eyebrow mb-2">Grounded in</div>{message.sources.slice(0, 3).map((source, i) => <div key={i} className="mb-2 text-xs"><span className="font-semibold">{source.title}</span><span className="ml-2 opacity-65">{source.excerpt}</span></div>)}</div> : null}</div></div>)}{pending && <div className="flex items-center gap-2 text-sm text-muted-foreground"><span className="size-2 animate-pulse-soft rounded-full bg-accent" />Thinking across your context…</div>}</div><form onSubmit={submit} className="border-t border-border bg-background/45 p-4"><div className="flex items-end gap-2 rounded-xl border border-input bg-card p-2"><button type="button" data-testid="button-chat-attach" className="rounded-lg p-2 text-muted-foreground hover:bg-muted"><Paperclip size={17} /></button><textarea data-testid="input-chat-message" value={value} onChange={(e) => setValue(e.target.value)} onKeyDown={(e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); submit(e); } }} placeholder="Write to JARVIS…" className="max-h-32 min-h-10 flex-1 resize-none bg-transparent px-2 py-2 text-sm outline-none" /><button data-testid="button-send-chat" disabled={pending || !value.trim()} className="grid size-10 place-items-center rounded-lg bg-primary text-primary-foreground"><Send size={16} /></button></div><div className="mt-2 px-2 text-[10px] text-muted-foreground">Enter to send · Shift + Enter for a new line</div></form></div></div>;
}

function KnowledgePage() {
  const [q, setQ] = useState(''); const [submitted, setSubmitted] = useState(''); const { data, isLoading } = useSearchKnowledge({ q: submitted }, { query: { enabled: submitted.length > 0, queryKey: getSearchKnowledgeQueryKey({ q: submitted }) } });
  return <div className="animate-rise"><PageHeading eyebrow="Cross-domain recall" title="Knowledge" body="One search across your memories, goals, meetings, documents, and reminders." /><form onSubmit={(e) => { e.preventDefault(); setSubmitted(q.trim()); }} className="relative mb-8 max-w-3xl"><Search className="absolute left-4 top-3.5 text-muted-foreground" size={18} /><Input data-testid="input-knowledge-search" value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search your whole life…" className="h-12 pl-11 pr-28" /><Button data-testid="button-submit-knowledge" className="absolute right-1.5 top-1.5 h-9">Search</Button></form>{!submitted ? <Empty icon={Search} title="Ask your context" body="Try a person, a project, or a phrase you remember. JARVIS will look across every surface." /> : isLoading ? <div className="grid gap-3">{[1, 2, 3].map((i) => <Skeleton key={i} className="h-24" />)}</div> : data?.length ? <div className="grid gap-3">{data.map((item, i) => <article key={i} data-testid={`result-knowledge-${i}`} className="panel p-5"><div className="flex gap-4"><div className="mt-1 rounded-md bg-secondary p-2 text-primary">{item.kind === 'document' ? <FileText size={16} /> : item.kind === 'goal' ? <Target size={16} /> : <BrainCircuit size={16} />}</div><div><div className="flex flex-wrap items-center gap-2"><span className="font-mono text-[10px] uppercase tracking-wider text-accent">{item.kind}</span><span className="text-[11px] text-muted-foreground">{dateLabel(item.occurredAt)}</span></div><h2 className="mt-2 font-semibold">{item.title}</h2><p className="mt-1 text-sm leading-6 text-muted-foreground">{item.excerpt}</p></div></div></article>)}</div> : <Empty icon={Search} title="No thread found" body={`Nothing matched “${submitted}”. Try a broader phrase.`} />}</div>;
}

function GrowthPage() {
  const { data, isLoading } = useGetGrowth(); if (isLoading) return <div className="grid gap-4 md:grid-cols-3"><Skeleton className="h-36" /><Skeleton className="h-36" /><Skeleton className="h-36" /></div>; if (!data) return <Empty icon={TrendingUp} title="Growth is waiting" body="Keep using JARVIS and your patterns will become visible here." />;
  const metrics = [{ label: 'XP earned', value: data.xp, icon: Zap }, { label: 'Current level', value: data.level, icon: Gauge }, { label: 'Day streak', value: data.streak, icon: Flame }, { label: 'Completion rate', value: `${data.completionRate}%`, icon: Check }, { label: 'Tasks completed', value: data.completedTasks, icon: Check }, { label: 'Memories created', value: data.memoriesCreated, icon: BrainCircuit }];
  return <div className="animate-rise"><PageHeading eyebrow="Your becoming" title="Growth" body="A living read on the momentum you are building through attention and follow-through." /><section className="mb-5 grid gap-5 lg:grid-cols-[1fr_1.3fr]"><div className="rounded-2xl bg-sidebar p-7 text-sidebar-foreground"><div className="eyebrow text-accent">Level {data.level}</div><div className="mt-3 flex items-end gap-3"><span className="font-serif text-7xl">{data.xp}</span><span className="mb-2 font-mono text-xs text-sidebar-foreground/55">XP</span></div><div className="mt-7 h-2 overflow-hidden rounded-full bg-sidebar-accent"><div className="h-full rounded-full bg-accent" style={{ width: `${Math.min(100, data.nextLevelXp ? data.xp / data.nextLevelXp * 100 : 0)}%` }} /></div><div className="mt-2 flex justify-between font-mono text-[10px] text-sidebar-foreground/50"><span>Current momentum</span><span>{data.nextLevelXp} XP next level</span></div></div><div className="grid gap-4 sm:grid-cols-2"><Stat label="Active goals" value={data.activeGoals} detail="In motion" icon={Target} /><Stat label="Completed goals" value={data.completedGoals} detail="Promises kept" icon={Check} /><Stat label="Documents" value={data.documentsUploaded} detail="Ideas indexed" icon={FileText} /><Stat label="Meetings" value={data.meetingsProcessed} detail="Conversations processed" icon={CalendarDays} /></div></section><section className="panel p-6"><div className="eyebrow">Emerging skills</div><h2 className="mt-1 font-serif text-2xl">What your activity is teaching you</h2><div className="mt-6 flex flex-wrap gap-3">{data.skills?.length ? data.skills.map((skill) => <div key={skill} className="flex items-center gap-2 rounded-full border border-border bg-background px-4 py-2 text-sm"><span className="size-2 rounded-full bg-accent" />{skill}</div>) : <p className="text-sm text-muted-foreground">Your skills will appear as patterns accumulate.</p>}</div></section><div className="mt-5 grid gap-4 sm:grid-cols-3"><Stat label="Completion rate" value={`${data.completionRate}%`} detail="Goals and tasks" icon={TrendingUp} /><Stat label="Completed tasks" value={data.completedTasks} detail="Small steps count" icon={Check} /><Stat label="Streak" value={`${data.streak} days`} detail="Attention compounds" icon={Flame} /></div></div>;
}

function MeetingsPage() {
  const { data, isLoading } = useListMeetings(); const qc = useQueryClient(); const [composer, setComposer] = useState(false); const [selected, setSelected] = useState<number | null>(null); const [form, setForm] = useState({ title: '', transcript: '', meetingDate: '' }); const selectedMeeting = data?.find((x) => x.id === selected);
  const process = async (e: FormEvent) => { e.preventDefault(); await createMeeting({ ...form, meetingDate: form.meetingDate || null }); await qc.invalidateQueries({ queryKey: getListMeetingsQueryKey() }); await qc.invalidateQueries({ queryKey: getGetDashboardQueryKey() }); setForm({ title: '', transcript: '', meetingDate: '' }); setComposer(false); };
  const remove = async (id: number) => { if (!window.confirm('Delete this meeting?')) return; await deleteMeeting(id); await qc.invalidateQueries({ queryKey: getListMeetingsQueryKey() }); setSelected(null); };
  return <div className="animate-rise"><PageHeading eyebrow="Conversation memory" title="Meetings" body="Turn conversations into decisions you can find, trust, and act on." action={<Button data-testid="button-new-meeting" onClick={() => setComposer(true)}><Plus size={16} />Process transcript</Button>} />{composer && <form onSubmit={process} className="panel mb-6 grid gap-4 p-5 md:p-6"><div className="flex items-center justify-between"><h2 className="font-serif text-2xl">Process a meeting</h2><button type="button" data-testid="button-close-meeting-form" onClick={() => setComposer(false)}><X size={18} /></button></div><Field label="Meeting title"><Input data-testid="input-meeting-title" required value={form.title} onChange={(e) => setForm({ ...form, title: e.target.value })} placeholder="Weekly product sync" /></Field><Field label="Transcript" hint="Paste at least 20 characters. JARVIS will extract the useful parts."><Textarea data-testid="input-meeting-transcript" required minLength={20} className="min-h-48" value={form.transcript} onChange={(e) => setForm({ ...form, transcript: e.target.value })} placeholder="Paste the raw transcript here…" /></Field><Field label="Meeting date"><Input data-testid="input-meeting-date" type="datetime-local" value={form.meetingDate} onChange={(e) => setForm({ ...form, meetingDate: e.target.value })} /></Field><div className="flex justify-end gap-2"><Button variant="quiet" type="button" data-testid="button-cancel-meeting" onClick={() => setComposer(false)}>Cancel</Button><Button data-testid="button-process-meeting"><Sparkles size={15} />Process with JARVIS</Button></div></form>}<div className="grid gap-5 lg:grid-cols-[.8fr_1.2fr]">{isLoading ? <div className="grid gap-3"><Skeleton className="h-24" /><Skeleton className="h-24" /></div> : data?.length ? <div className="grid content-start gap-3">{data.map((meeting) => <button key={meeting.id} data-testid={`button-select-meeting-${meeting.id}`} onClick={() => setSelected(meeting.id)} className={cx('panel p-4 text-left transition hover:-translate-y-0.5', selected === meeting.id && 'border-primary ring-2 ring-primary/15')}><div className="flex items-start justify-between gap-3"><div><div className="font-semibold">{meeting.title}</div><div className="mt-1 text-xs text-muted-foreground">{dateLabel(meeting.meetingDate)} · {meeting.actionItems?.length || 0} action items</div></div><ChevronRight size={16} className="mt-1 text-muted-foreground" /></div></button>)}</div> : <Empty icon={CalendarDays} title="No meetings processed" body="Paste a transcript and let JARVIS hold onto the decisions." action={<Button data-testid="button-empty-add-meeting" onClick={() => setComposer(true)}>Process a transcript</Button>} />}<MeetingDetail meeting={selectedMeeting} onDelete={remove} /></div></div>;
}
function MeetingDetail({ meeting, onDelete }: { meeting?: { id: number; title: string; summary: string; decisions: string[]; actionItems: string[]; participants: string[]; transcript: string; meetingDate: string | null }; onDelete: (id: number) => void }) { if (!meeting) return <div className="panel hidden min-h-[420px] place-items-center lg:grid"><div className="text-center"><CalendarDays className="mx-auto text-muted-foreground" size={24} /><p className="mt-3 text-sm text-muted-foreground">Select a meeting to inspect its signal.</p></div></div>; return <article data-testid={`detail-meeting-${meeting.id}`} className="panel p-6"><div className="flex items-start justify-between gap-3"><div><div className="eyebrow">{dateLabel(meeting.meetingDate)}</div><h2 className="mt-2 font-serif text-3xl">{meeting.title}</h2></div><button data-testid={`button-delete-meeting-${meeting.id}`} onClick={() => onDelete(meeting.id)} className="rounded-md p-2 text-muted-foreground hover:bg-destructive/10 hover:text-destructive"><Trash2 size={16} /></button></div><div className="mt-8 grid gap-6"><div><div className="eyebrow">Summary</div><p className="mt-2 text-sm leading-7">{meeting.summary || 'No summary returned.'}</p></div><div><div className="eyebrow">Decisions</div>{meeting.decisions?.length ? <ul className="mt-2 grid gap-2">{meeting.decisions.map((x, i) => <li key={i} className="flex gap-2 text-sm leading-6"><Check size={15} className="mt-1 shrink-0 text-primary" />{x}</li>)}</ul> : <p className="mt-2 text-sm text-muted-foreground">No decisions extracted.</p>}</div><div><div className="eyebrow">Action items</div>{meeting.actionItems?.length ? <ul className="mt-2 grid gap-2">{meeting.actionItems.map((x, i) => <li key={i} className="flex gap-2 text-sm leading-6"><Circle size={12} className="mt-1.5 shrink-0 text-accent" />{x}</li>)}</ul> : <p className="mt-2 text-sm text-muted-foreground">No action items extracted.</p>}</div></div></article>; }

function DocumentsPage() {
  const { data, isLoading } = useListDocuments(); const qc = useQueryClient(); const [selected, setSelected] = useState<number | null>(null); const [query, setQuery] = useState(''); const [answer, setAnswer] = useState(''); const [pending, setPending] = useState(false); const [addText, setAddText] = useState(false); const [textForm, setTextForm] = useState({ title: '', content: '' }); const detail = useGetDocument(selected || 0, { query: { enabled: !!selected, queryKey: getGetDocumentQueryKey(selected || 0) } });
  const upload = async (file: File) => { await uploadDocument({ file }); await qc.invalidateQueries({ queryKey: getListDocumentsQueryKey() }); };
  const saveText = async (e: FormEvent) => { e.preventDefault(); await createDocument({ filename: `${textForm.title || 'untitled'}.txt`, title: textForm.title, content: textForm.content, fileSize: textForm.content.length }); await qc.invalidateQueries({ queryKey: getListDocumentsQueryKey() }); setTextForm({ title: '', content: '' }); setAddText(false); };
  const ask = async (e: FormEvent) => { e.preventDefault(); if (!query.trim()) return; setPending(true); try { const res = await queryDocuments({ query, documentId: selected || undefined }); setAnswer(res.answer); } catch { setAnswer('I could not query that document right now.'); } finally { setPending(false); } };
  const remove = async (id: number) => { if (!window.confirm('Delete this document?')) return; await deleteDocument(id); await qc.invalidateQueries({ queryKey: getListDocumentsQueryKey() }); setSelected(null); };
  return <div className="animate-rise"><PageHeading eyebrow="External context" title="Documents" body="Index the things you read so your questions can reach beyond your immediate memory." action={<div className="flex flex-wrap gap-2"><Button data-testid="button-add-text-document" variant="outline" onClick={() => setAddText(true)}><Plus size={15} />Add text</Button><label data-testid="button-upload-document" className="inline-flex cursor-pointer items-center justify-center gap-2 rounded-lg bg-primary px-3.5 py-2 text-sm font-semibold text-primary-foreground hover:opacity-90"><Upload size={16} />Upload file<input data-testid="input-upload-document" type="file" accept=".pdf,.txt,.md" className="hidden" onChange={(e) => { const file = e.target.files?.[0]; if (file) upload(file); }} /></label></div>} />{addText && <form onSubmit={saveText} className="panel mb-6 grid gap-4 p-5 md:p-6"><div className="flex items-center justify-between"><h2 className="font-serif text-2xl">Index a note</h2><button type="button" data-testid="button-close-text-document" onClick={() => setAddText(false)}><X size={18} /></button></div><Field label="Title"><Input data-testid="input-text-document-title" required value={textForm.title} onChange={(e) => setTextForm({ ...textForm, title: e.target.value })} /></Field><Field label="Text content"><Textarea data-testid="input-text-document-content" required className="min-h-40" value={textForm.content} onChange={(e) => setTextForm({ ...textForm, content: e.target.value })} placeholder="Paste a note, an idea, or a reference…" /></Field><div className="flex justify-end"><Button data-testid="button-save-text-document">Index text</Button></div></form>}<div className="grid gap-5 lg:grid-cols-[.8fr_1.2fr]">{isLoading ? <div className="grid gap-3"><Skeleton className="h-24" /><Skeleton className="h-24" /></div> : data?.length ? <div className="grid content-start gap-3">{data.map((doc) => <button key={doc.id} data-testid={`button-select-document-${doc.id}`} onClick={() => { setSelected(doc.id); setAnswer(''); }} className={cx('panel p-4 text-left transition hover:-translate-y-0.5', selected === doc.id && 'border-primary ring-2 ring-primary/15')}><div className="flex items-start gap-3"><div className="rounded-md bg-secondary p-2 text-primary"><FileText size={17} /></div><div className="min-w-0 flex-1"><div className="truncate font-semibold">{doc.title || doc.filename}</div><div className="mt-1 text-xs text-muted-foreground">{doc.filename} · {doc.chunkCount} chunks</div><div className="mt-3 flex items-center gap-2"><span className={cx('size-1.5 rounded-full', doc.processingStatus === 'ready' ? 'bg-primary' : 'bg-accent')} /><span className="font-mono text-[10px] uppercase tracking-wider text-muted-foreground">{doc.processingStatus}</span></div></div><ChevronRight size={16} className="mt-1 text-muted-foreground" /></div></button>)}</div> : <Empty icon={FileText} title="No documents indexed" body="Upload a PDF or text file to give JARVIS a wider reading desk." action={<label data-testid="button-empty-upload-document" className="inline-flex cursor-pointer items-center gap-2 rounded-lg bg-primary px-3.5 py-2 text-sm font-semibold text-primary-foreground"><Upload size={15} />Choose a file<input type="file" className="hidden" accept=".pdf,.txt,.md" onChange={(e) => { const file = e.target.files?.[0]; if (file) upload(file); }} /></label>} />}<section className="panel min-h-[420px] p-6">{selected && detail.data ? <><div className="flex items-start justify-between"><div><div className="eyebrow">Document reader</div><h2 className="mt-2 font-serif text-3xl">{detail.data.title}</h2></div><button data-testid={`button-delete-document-${selected}`} onClick={() => remove(selected)} className="rounded-md p-2 text-muted-foreground hover:bg-destructive/10 hover:text-destructive"><Trash2 size={16} /></button></div><div className="mt-6 rounded-lg bg-secondary/60 p-4 text-sm leading-7 text-secondary-foreground">{detail.data.textPreview || 'No preview available.'}</div><form onSubmit={ask} className="mt-6 flex gap-2"><Input data-testid="input-document-query" value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Ask this document a question…" /><Button data-testid="button-query-document" disabled={pending}>Ask</Button></form>{answer && <div data-testid="text-document-answer" className="mt-4 rounded-lg border border-primary/20 bg-primary/5 p-4 text-sm leading-7">{answer}</div>}</> : <div className="grid min-h-[360px] place-items-center text-center"><div><BookOpen className="mx-auto text-muted-foreground" size={24} /><p className="mt-3 text-sm text-muted-foreground">Select a document to read and query it.</p></div></div>}</section></div></div>;
}

function AnalyticsPage() {
  const { data, isLoading } = useGetTimeline(); const events = data || []; return <div className="animate-rise"><PageHeading eyebrow="A life in motion" title="Activity" body="A quiet timeline of the moments JARVIS helped you notice, finish, and remember." /><div className="grid gap-5 lg:grid-cols-[1.2fr_.8fr]"><section className="panel p-6"><div className="mb-6 flex items-center justify-between"><div><div className="eyebrow">Timeline</div><h2 className="mt-1 font-serif text-2xl">Recent signal</h2></div><Activity size={18} className="text-primary" /></div>{isLoading ? <div className="grid gap-5">{[1, 2, 3, 4].map((i) => <Skeleton key={i} className="h-16" />)}</div> : events.length ? <div className="relative ml-2 border-l border-border pl-7">{events.map((event, i) => <div key={event.id} data-testid={`timeline-event-${i}`} className="relative mb-7 last:mb-0"><span className="absolute -left-[35px] top-1.5 grid size-4 place-items-center rounded-full border-2 border-background bg-accent"><span className="size-1 rounded-full bg-sidebar" /></span><div className="flex flex-wrap items-center gap-2"><span className="font-mono text-[10px] uppercase tracking-wider text-accent">{event.kind}</span><span className="text-[10px] text-muted-foreground">{dateLabel(event.occurredAt)}</span></div><h3 className="mt-1 text-sm font-semibold">{event.title}</h3><p className="mt-1 text-sm leading-6 text-muted-foreground">{event.description}</p></div>)}</div> : <Empty icon={Activity} title="Your timeline starts here" body="Create a memory, goal, meeting, or document to see your activity take shape." />}</section><section className="grid content-start gap-4"><div className="rounded-2xl bg-sidebar p-6 text-sidebar-foreground"><div className="eyebrow text-accent">A useful question</div><h2 className="mt-4 font-serif text-3xl leading-tight">What keeps showing up?</h2><p className="mt-4 text-sm leading-7 text-sidebar-foreground/60">Patterns are easier to act on once they have somewhere to land. Explore your growth metrics for the longer arc.</p><Link data-testid="link-analytics-growth" href="/growth" className="mt-6 inline-flex items-center gap-2 text-sm font-semibold text-accent hover:underline">See growth <ArrowUpRight size={15} /></Link></div><Stat label="Events captured" value={events.length} detail="Across your workspace" icon={Activity} /><Stat label="Context surfaces" value="5" detail="Memory · goals · meetings · docs · reminders" icon={BrainCircuit} /></section></div></div>;
}

function SettingsPage({ user }: { user: User }) {
  const [theme, setTheme] = useState(document.documentElement.classList.contains('dark') ? 'dark' : 'light'); const [saved, setSaved] = useState(false);
  const changeTheme = (value: string) => { setTheme(value); document.documentElement.classList.toggle('dark', value === 'dark'); localStorage.setItem('jarvis-theme', value); setSaved(true); };
  return <div className="animate-rise max-w-3xl"><PageHeading eyebrow="Workspace preferences" title="Settings" body="Make JARVIS feel like a place you want to return to." /><section className="panel divide-y divide-border/70"><div className="p-6"><div className="eyebrow">Account</div><div className="mt-5 flex items-center gap-4"><div className="grid size-14 place-items-center rounded-full bg-primary font-serif text-xl text-primary-foreground">{initials(user.name)}</div><div><div data-testid="settings-user-name" className="font-semibold">{user.name}</div><div data-testid="settings-user-email" className="mt-1 text-sm text-muted-foreground">{user.email}</div></div></div></div><div className="p-6"><div className="eyebrow">Appearance</div><div className="mt-3 flex flex-col justify-between gap-4 sm:flex-row sm:items-center"><div><h3 className="text-sm font-semibold">Theme preference</h3><p className="mt-1 text-xs text-muted-foreground">Choose how your command center meets the light.</p></div><div className="flex rounded-lg border border-border p-1">{['light', 'dark'].map((value) => <button key={value} data-testid={`button-theme-${value}`} onClick={() => changeTheme(value)} className={cx('rounded-md px-4 py-2 text-xs font-semibold capitalize', theme === value ? 'bg-primary text-primary-foreground' : 'text-muted-foreground hover:bg-muted')}>{value}</button>)}</div></div></div><div className="p-6"><div className="eyebrow">Data philosophy</div><p className="mt-3 max-w-xl text-sm leading-7 text-muted-foreground">JARVIS is designed to make your own context more useful, not noisier. Every memory, goal, and conversation stays tied to the workspace you built.</p></div></section>{saved && <div data-testid="status-settings-saved" className="mt-4 flex items-center gap-2 text-sm text-primary"><Check size={15} />Preference saved</div>}</div>;
}

function RemindersPanel() {
  const { data } = useListReminders(); const qc = useQueryClient(); const [form, setForm] = useState(false); const [title, setTitle] = useState('');
  const save = async (e: FormEvent) => { e.preventDefault(); if (!title.trim()) return; await createReminder({ title, dueAt: new Date(Date.now() + 86400000).toISOString() }); await qc.invalidateQueries({ queryKey: getListRemindersQueryKey() }); setTitle(''); setForm(false); };
  const complete = async (id: number, status: string) => { await updateReminder(id, { status: status === 'completed' ? 'pending' : 'completed' }); await qc.invalidateQueries({ queryKey: getListRemindersQueryKey() }); };
  const remove = async (id: number) => { if (!window.confirm('Delete this reminder?')) return; await deleteReminder(id); await qc.invalidateQueries({ queryKey: getListRemindersQueryKey() }); };
  return <section className="panel p-6"><div className="flex items-center justify-between"><div><div className="eyebrow">Nudges</div><h2 className="mt-1 font-serif text-2xl">Reminders</h2></div><button data-testid="button-add-reminder" onClick={() => setForm(!form)} className="rounded-md p-2 text-primary hover:bg-muted"><Plus size={17} /></button></div>{form && <form onSubmit={save} className="mt-4 flex gap-2"><Input data-testid="input-reminder-title" value={title} onChange={(e) => setTitle(e.target.value)} placeholder="Remember to…" /><Button data-testid="button-save-reminder">Add</Button></form>}<div className="mt-5 grid gap-3">{data?.slice(0, 5).map((item) => <div key={item.id} data-testid={`row-dashboard-reminder-${item.id}`} className="group flex items-center gap-3 border-b border-border/60 pb-3 last:border-0"><button data-testid={`button-complete-reminder-${item.id}`} onClick={() => complete(item.id, item.status)} className={cx('grid size-5 place-items-center rounded-full border', item.status === 'completed' ? 'border-primary bg-primary text-primary-foreground' : 'border-border')}><Check size={11} /></button><span className={cx('flex-1 text-sm', item.status === 'completed' && 'text-muted-foreground line-through')}>{item.title}</span><span className="font-mono text-[10px] text-muted-foreground">{dateLabel(item.dueAt)}</span><button data-testid={`button-delete-reminder-${item.id}`} onClick={() => remove(item.id)} className="rounded p-1 text-muted-foreground opacity-0 hover:text-destructive group-hover:opacity-100"><Trash2 size={13} /></button></div>)}</div></section>;
}

function AppRouter() {
  const [location] = useLocation(); const authRoute = location === '/login' || location === '/register'; const current = useGetCurrentUser({ query: { enabled: !authRoute, queryKey: getGetCurrentUserQueryKey() } });
  if (authRoute) return <Switch><Route path="/login"><AuthPage mode="login" /></Route><Route path="/register"><AuthPage mode="register" /></Route></Switch>;
  if (current.isLoading) return <div className="grid min-h-[100dvh] place-items-center bg-background"><div className="text-center"><div className="mx-auto grid size-12 place-items-center rounded-2xl bg-sidebar text-accent animate-pulse-soft"><Sparkles size={20} /></div><div className="mt-4 font-mono text-[10px] uppercase tracking-[.2em] text-muted-foreground">Opening context</div></div></div>;
  if (current.isError || !current.data) return <AuthPage mode="login" />;
  const user = current.data;
  return <Shell user={user}><Switch><Route path="/" component={DashboardPage} /><Route path="/chat" component={ChatPage} /><Route path="/memory" component={MemoryPage} /><Route path="/knowledge" component={KnowledgePage} /><Route path="/goals" component={GoalsPage} /><Route path="/growth" component={GrowthPage} /><Route path="/meetings" component={MeetingsPage} /><Route path="/documents" component={DocumentsPage} /><Route path="/analytics" component={AnalyticsPage} /><Route path="/settings"><SettingsPage user={user} /></Route><Route component={NotFound} /></Switch></Shell>;
}
function App() { useEffect(() => { document.documentElement.classList.toggle('dark', localStorage.getItem('jarvis-theme') === 'dark'); }, []); return <QueryClientProvider client={queryClient}><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><AppRouter /></WouterRouter></QueryClientProvider>; }
export default App;